{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "section_h2",
        "chopsticks_section",
        "pouring_section",
        "elders_section",
        "manners_section",
        "quick_actions_h3",
        "quick_actions_buttons_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Korean Dining Etiquette Essentials",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Dining in South Korea is a rich cultural experience steeped in tradition and respect, especially towards elders. As a foreign visitor, understanding these customs will enhance your experience and show appreciation for local culture."
      },
      "children": []
    },
    "section_h2": {
      "type": "Text",
      "props": {
        "text": "Key Practices for a Respectful Meal",
        "variant": "h2"
      },
      "children": []
    },
    "chopsticks_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "chopsticks_h3",
        "chopsticks_list"
      ]
    },
    "chopsticks_h3": {
      "type": "Text",
      "props": {
        "text": "Chopsticks and Spoon Protocol",
        "variant": "h3"
      },
      "children": []
    },
    "chopsticks_list": {
      "type": "List",
      "props": {},
      "children": [
        "chopsticks_item_1",
        "chopsticks_item_2",
        "chopsticks_item_3",
        "chopsticks_item_4"
      ]
    },
    "chopsticks_item_1": {
      "type": "Text",
      "props": {
        "text": "Spoon Use: Use your spoon for rice and soup. It is the primary utensil for these items."
      },
      "children": []
    },
    "chopsticks_item_2": {
      "type": "Text",
      "props": {
        "text": "Chopstick Use: Use chopsticks for side dishes (banchan). Never stick chopsticks upright in your rice bowl, as this resembles offerings to the deceased."
      },
      "children": []
    },
    "chopsticks_item_3": {
      "type": "Text",
      "props": {
        "text": "Resting Utensils: When not in use, place your spoon and chopsticks on a chopstick rest or neatly beside your bowl, not directly in the food."
      },
      "children": []
    },
    "chopsticks_item_4": {
      "type": "Text",
      "props": {
        "text": "No Pointing: Avoid using chopsticks to point at people or tap on bowls."
      },
      "children": []
    },
    "pouring_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "pouring_header_stack",
        "pouring_list"
      ]
    },
    "pouring_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "pouring_icon",
        "pouring_h3"
      ]
    },
    "pouring_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000050_01_2_cup-straw.svg"
      },
      "children": []
    },
    "pouring_h3": {
      "type": "Text",
      "props": {
        "text": "Pouring and Receiving Beverages",
        "variant": "h3"
      },
      "children": []
    },
    "pouring_list": {
      "type": "List",
      "props": {},
      "children": [
        "pouring_item_1",
        "pouring_item_2",
        "pouring_item_3",
        "pouring_item_4"
      ]
    },
    "pouring_item_1": {
      "type": "Text",
      "props": {
        "text": "Pour for Others: Always pour drinks for others before yourself, starting with the eldest person at the table."
      },
      "children": []
    },
    "pouring_item_2": {
      "type": "Text",
      "props": {
        "text": "Two-Handed Pour: When pouring for an elder, hold the bottle or pitcher with two hands as a sign of respect."
      },
      "children": []
    },
    "pouring_item_3": {
      "type": "Text",
      "props": {
        "text": "Two-Handed Receive: When someone, especially an elder, pours a drink for you, hold your glass with both hands to receive it."
      },
      "children": []
    },
    "pouring_item_4": {
      "type": "Text",
      "props": {
        "text": "Drinking Alcohol: If drinking alcohol with an elder, it is customary to turn your head slightly away from them when you take a sip."
      },
      "children": []
    },
    "elders_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "elders_header_stack",
        "elders_list"
      ]
    },
    "elders_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "elders_icon",
        "elders_h3"
      ]
    },
    "elders_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000050_01_3_person-arms-up.svg"
      },
      "children": []
    },
    "elders_h3": {
      "type": "Text",
      "props": {
        "text": "Respecting Elders at the Table",
        "variant": "h3"
      },
      "children": []
    },
    "elders_list": {
      "type": "List",
      "props": {},
      "children": [
        "elders_item_1",
        "elders_item_2",
        "elders_item_3",
        "elders_item_4"
      ]
    },
    "elders_item_1": {
      "type": "Text",
      "props": {
        "text": "Start Eating: Wait for the eldest person at the table to pick up their spoon or chopsticks before you begin eating."
      },
      "children": []
    },
    "elders_item_2": {
      "type": "Text",
      "props": {
        "text": "Finishing Meals: Do not leave the table before elders have finished their meal, unless you are explicitly excused."
      },
      "children": []
    },
    "elders_item_3": {
      "type": "Text",
      "props": {
        "text": "Offer and Receive: When offering or receiving food or serving dishes, especially to or from an elder, use two hands as a gesture of respect."
      },
      "children": []
    },
    "elders_item_4": {
      "type": "Text",
      "props": {
        "text": "Addressing Elders: Use appropriate honorifics and a respectful tone when speaking to elders."
      },
      "children": []
    },
    "manners_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "manners_header_stack",
        "manners_list"
      ]
    },
    "manners_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "manners_icon",
        "manners_h3"
      ]
    },
    "manners_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000050_01_4_table.svg"
      },
      "children": []
    },
    "manners_h3": {
      "type": "Text",
      "props": {
        "text": "General Table Manners",
        "variant": "h3"
      },
      "children": []
    },
    "manners_list": {
      "type": "List",
      "props": {},
      "children": [
        "manners_item_1",
        "manners_item_2",
        "manners_item_3",
        "manners_item_4"
      ]
    },
    "manners_item_1": {
      "type": "Text",
      "props": {
        "text": "Noise Levels: Avoid making excessive noise while eating, although slurping soup can be acceptable."
      },
      "children": []
    },
    "manners_item_2": {
      "type": "Text",
      "props": {
        "text": "Nose Blowing: Refrain from blowing your nose at the dining table."
      },
      "children": []
    },
    "manners_item_3": {
      "type": "Text",
      "props": {
        "text": "Reaching: Do not reach across the table for dishes; politely ask for them to be passed to you."
      },
      "children": []
    },
    "manners_item_4": {
      "type": "Text",
      "props": {
        "text": "Finishing Food: It's generally polite to try and finish all the food on your plate, especially rice."
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "learn_more_button",
        "travel_guide_button"
      ]
    },
    "learn_more_button": {
      "type": "Button",
      "props": {
        "label": "Learn More Korean Culture"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.korea.net/AboutKorea/Korean-Life/Culture-and-Arts"
          }
        }
      },
      "children": []
    },
    "travel_guide_button": {
      "type": "Button",
      "props": {
        "label": "Korean Travel Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://english.visitkorea.or.kr/enu/index.kto"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "korea_net_button",
        "visit_korea_button"
      ]
    },
    "korea_net_button": {
      "type": "Button",
      "props": {
        "label": "Korea.net: The Official Website of the Republic of Korea"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.korea.net/"
          }
        }
      },
      "children": []
    },
    "visit_korea_button": {
      "type": "Button",
      "props": {
        "label": "VisitKorea: Official Korea Tourism Organization"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://english.visitkorea.or.kr/enu/index.kto"
          }
        }
      },
      "children": []
    }
  }
}
